// Fichier : src/AteliersInscrits.tsx
import { useEffect, useState } from "react";

export type AtelierInscrit = {
  id: string;
  titre: string;
};

type EtatListe =
  | { phase: "chargement" }
  | { phase: "succes"; ateliers: AtelierInscrit[] }
  | { phase: "erreur"; message: string };

type AteliersInscritsProps = {
  idMembre: string;
  onDesinscrire: (idAtelier: string) => void;
};

export function AteliersInscrits({ idMembre, onDesinscrire }: AteliersInscritsProps) {
  const [etat, setEtat] = useState<EtatListe>({ phase: "chargement" });

  useEffect(() => {
    let actif = true;
    setEtat({ phase: "chargement" });

    fetch(`/api/membres/${idMembre}/inscriptions`)
      .then((reponse) => {
        if (!reponse.ok) throw new Error("statut invalide");
        return reponse.json() as Promise<AtelierInscrit[]>;
      })
      .then((ateliers) => {
        if (actif) setEtat({ phase: "succes", ateliers });
      })
      .catch(() => {
        if (actif) setEtat({ phase: "erreur", message: "La liste n'a pas pu être chargée" });
      });

    return () => {
      actif = false;
    };
  }, [idMembre]);

  if (etat.phase === "chargement") {
    return <p role="status">Chargement de vos inscriptions...</p>;
  }

  if (etat.phase === "erreur") {
    return <p role="alert">{etat.message}</p>;
  }

  if (etat.ateliers.length === 0) {
    return (
      <section>
        <h2>Mes inscriptions</h2>
        <p>Vous n'êtes inscrit(e) à aucun atelier pour le moment.</p>
      </section>
    );
  }

  return (
    <section aria-labelledby="titre-inscriptions">
      <h2 id="titre-inscriptions">Mes inscriptions</h2>
      <ul>
        {etat.ateliers.map((atelier) => (
          <li key={atelier.id}>
            {atelier.titre}
            <button
              type="button"
              aria-label={`Se désinscrire de l'atelier ${atelier.titre}`}
              onClick={() => onDesinscrire(atelier.id)}
            >
              <svg aria-hidden="true" focusable="false" viewBox="0 0 24 24">
                <path d="M6 6l12 12M18 6L6 18" />
              </svg>
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}

// Fichier : src/AteliersInscrits.test.tsx
import axe from "axe-core";
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, expect, it, vi } from "vitest";

const ateliers = [
  { id: "a-14", titre: "Premiers pas avec le clavier" },
  { id: "a-15", titre: "Retrouver ses photos" },
];

function reseauSimule(corps: unknown) {
  return vi.fn().mockResolvedValue({ ok: true, json: async () => corps });
}

afterEach(() => {
  vi.unstubAllGlobals();
});

it("affiche les inscriptions puis retire celle qui est annulée", async () => {
  vi.stubGlobal("fetch", reseauSimule(ateliers));
  const onDesinscrire = vi.fn();
  const utilisateur = userEvent.setup();
  render(<AteliersInscrits idMembre="m-3" onDesinscrire={onDesinscrire} />);

  expect(await screen.findByText("Premiers pas avec le clavier")).toBeInTheDocument();
  expect(screen.getByText("Retrouver ses photos")).toBeInTheDocument();

  const boutons = screen.getAllByRole("button", { name: /Se désinscrire de l'atelier/ });
  await utilisateur.click(boutons[0]);

  expect(onDesinscrire).toHaveBeenCalledWith("a-14");
  expect(screen.queryByText("Premiers pas avec le clavier")).not.toBeInTheDocument();
});

it("affiche l'état vide quand aucune inscription n'existe", async () => {
  vi.stubGlobal("fetch", reseauSimule([]));
  render(<AteliersInscrits idMembre="m-3" onDesinscrire={() => {}} />);

  expect(
    await screen.findByText("Vous n'êtes inscrit(e) à aucun atelier pour le moment."),
  ).toBeInTheDocument();
  expect(screen.queryByRole("button")).not.toBeInTheDocument();
});

it("ne contient aucune violation d'accessibilité automatisable", async () => {
  vi.stubGlobal("fetch", reseauSimule(ateliers));
  const { container } = render(<AteliersInscrits idMembre="m-3" onDesinscrire={() => {}} />);
  await screen.findByText("Premiers pas avec le clavier");

  const resultats = await axe.run(container);
  expect(resultats.violations).toEqual([]);
});
